import{_ as e,o as r,c as t,a5 as h}from"./chunks/framework.D_J2JZBr.js";const p=JSON.parse('{"title":"特色培养项目","description":"汇总上科大 IC 相关暑期实训、上海创芯学院、IC 荣誉项目、人工智能荣誉班、校企联培、工艺制造专项班与本研一体课程入口。","frontmatter":{"title":"特色培养项目","description":"汇总上科大 IC 相关暑期实训、上海创芯学院、IC 荣誉项目、人工智能荣誉班、校企联培、工艺制造专项班与本研一体课程入口。"},"headers":[],"relativePath":"shanghaitech/programs.md","filePath":"shanghaitech/programs.md","lastUpdated":1795531638000}'),s={name:"shanghaitech/programs.md"};function n(i,a,o,l,c,g){return r(),t("div",null,[...a[0]||(a[0]=[h('<h1 id="特色培养项目" tabindex="-1">特色培养项目 <a class="header-anchor" href="#特色培养项目" aria-label="Permalink to &quot;特色培养项目&quot;">​</a></h1><p>上科大的 IC 学习机会不只在常规课堂：暑期实训帮助连接工业设计流程，课题组和公共平台支撑科研，专业学位与校企联合培养进一步连接工程现场。本页按「<strong>是什么 / 面向谁 / 怎么参与 / 官方入口</strong>」整理，不把不同层次的项目混为同一种招生或培养渠道。</p><div class="warning custom-block"><p class="custom-block-title">先分清适用对象与年份</p><p>以下是公开项目介绍，不是当前开放报名清单。2024、2025、2026 年的活动记录与招生通知都有时间边界；历史报名期限不能直接用于下一届。尤其注意：人工智能荣誉班、短期暑期培训、研究生联合培养三者的资格与培养要求不同。</p></div><h2 id="楷登电子-cadence-集成电路暑期实训" tabindex="-1">楷登电子（Cadence）集成电路暑期实训 <a class="header-anchor" href="#楷登电子-cadence-集成电路暑期实训" aria-label="Permalink to &quot;楷登电子（Cadence）集成电路暑期实训&quot;">​</a></h2><h3 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><p>由信息学院组织、与楷登电子（Cadence）合作开展的数字芯片设计与电子设计自动化（EDA）工具实训。</p><ul><li><strong>2024 年首期</strong>：官方报道记载 7 月 1 日开营、7 月 11 日结束，培训约两周，聚焦数字芯片设计工具与流程。</li><li><strong>2025 年第二期</strong>：官方报道明确其为电子学科平台与 Cadence 开展的第二期暑期实训，6 月 30 日开营、7 月 24 日结束，为期 25 天，并设置<strong>基础班和提高班</strong>。基础班覆盖 Genus 综合、Innovus 物理实现与 Tempus 时序签核；提高班聚焦低功耗数字全流程，采用项目实践与专家讨论结合的方式。</li><li><strong>2026 年版本</strong>：依据项目维护者的当年课程笔记整理，训练主线包括从 RTL 到 GDSII 的数字后端实现，配合理论课、工具实验、RISC-V 项目展示与问答、企业参访。此处是<strong>课程笔记版本</strong>，不将其当作官方招生简章；详细内容见 <a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/cadence-summer">Cadence 暑期实训</a>。</li></ul><h3 id="面向谁" tabindex="-1">面向谁 <a class="header-anchor" href="#面向谁" aria-label="Permalink to &quot;面向谁&quot;">​</a></h3><p>希望理解数字芯片实现与签核流程、愿意投入连续实操时间的学生。往年报道中有本研学生参与，但<strong>不能据此推断未来每一期都对所有年级、所有专业开放</strong>。已有数字电路、Verilog 与基本 Linux 能力，更有助于把精力放在实现约束和工具原理上。</p><h3 id="怎么参与" tabindex="-1">怎么参与 <a class="header-anchor" href="#怎么参与" aria-label="Permalink to &quot;怎么参与&quot;">​</a></h3><p>关注学院技能培训、电子学科平台及当年课程通知，确认报名对象、基础要求、班型、考核和环境安排。准备时可先学习 <a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/ee115b">EE115B</a>、<a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/ee113">EE113</a> 与 <a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/ee291f">EE291F</a>，不必先自行寻找商业软件或工艺包。</p><p><strong>官方入口</strong>：<a href="https://sist.shanghaitech.edu.cn/2024/0715/c2858a1098559/page.htm" target="_blank" rel="noreferrer">2024 年实训报道</a>、<a href="https://sist.shanghaitech.edu.cn/2025/0811/c2858a1114212/page.htm" target="_blank" rel="noreferrer">2025 年第二期报道</a>。</p><h2 id="上海创芯学院-sisi-联合培养" tabindex="-1">上海创芯学院（SISI）联合培养 <a class="header-anchor" href="#上海创芯学院-sisi-联合培养" aria-label="Permalink to &quot;上海创芯学院（SISI）联合培养&quot;">​</a></h2><h3 id="是什么-1" tabindex="-1">是什么 <a class="header-anchor" href="#是什么-1" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><p>上海创芯学院（SISI）由<strong>上海科技大学、上海交通大学、复旦大学共同参与创建</strong>，是一所汇聚高校、企业与产线资源的新型研发机构。根据与上科大的 <strong>2026 年联合招生简介</strong>，联合培养毕业授予上海科技大学<strong>电子信息（0854）专业学位</strong>，学生学籍归属上海科技大学。</p><p>项目强调芯片设计全流程工程能力，公开介绍列有学术导师、产业导师、战略导师的三位一体指导，以及专属优质流片机会。其「<strong>一生一芯</strong>」被明确列为<strong>学位授予硬性门槛</strong>：每位学生须完成从芯片架构设计、物理实现、流片制造到硅后验证的完整闭环，并通过实测指标考核。</p><div class="info custom-block"><p class="custom-block-title">不要混淆两个语境</p><p>这里的「一生一芯」指该联合培养项目公开规定的培养与学位要求；它不是上科大所有学生的统一毕业要求，也不应与 <a href="/shanghaitech-ic-wiki-dev.github.io/competitions/projects/ysyx">开源一生一芯学习项目</a> 的参与资格、考核与学位制度混为一谈。</p></div><h3 id="面向谁-1" tabindex="-1">面向谁 <a class="header-anchor" href="#面向谁-1" aria-label="Permalink to &quot;面向谁&quot;">​</a></h3><p>计划接受电子信息专业学位培养、希望深入芯片工程全流程的研究生申请者。2026 年联合招生简介分别列有专业型博士和专业型硕士渠道；是否符合申请条件，需要看学校及学院相应年度招生章程。</p><h3 id="怎么参与-1" tabindex="-1">怎么参与 <a class="header-anchor" href="#怎么参与-1" aria-label="Permalink to &quot;怎么参与&quot;">​</a></h3><p>按上科大官方硕博招生流程报名、提交材料、接受审核与考核，并关注 SISI 的联合培养说明。2026 年简介对专业型硕士给出的报考说明为电子信息专业 <strong>01 电子科学与技术方向</strong>；这是当年口径，后续年度专业代码、方向与名额须重新核对，不直接套用。</p><p><strong>官方入口</strong>：<a href="https://sist.shanghaitech.edu.cn/2026/0402/c2858a1120477/page.htm" target="_blank" rel="noreferrer">2026 年联合招生简介</a>、<a href="https://www.sisi.edu.cn/" target="_blank" rel="noreferrer">上海创芯学院官网</a>。</p><h2 id="信息学院人工智能荣誉班" tabindex="-1">信息学院人工智能荣誉班 <a class="header-anchor" href="#信息学院人工智能荣誉班" aria-label="Permalink to &quot;信息学院人工智能荣誉班&quot;">​</a></h2><h3 id="是什么-2" tabindex="-1">是什么 <a class="header-anchor" href="#是什么-2" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><p>信息学院的定制化本科培养项目。<strong>2026 年通知为第二届选拔</strong>，聚焦大模型、机器人、人工智能芯片、具身智能，提供小班化教学、定制培养方案、前置修读课程，以及「三轮轮转 + 双向选择」的一对一导师制。</p><p>AI 芯片是关注领域之一，但这不等于项目只围绕集成电路设置；它与 <a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/honors-program/">IC 荣誉项目</a> 是两个不同的项目，不能混称。</p><h3 id="面向谁-2" tabindex="-1">面向谁 <a class="header-anchor" href="#面向谁-2" aria-label="Permalink to &quot;面向谁&quot;">​</a></h3><p><strong>2026 年选拔通知仅面向 2026 级计算机科学与技术专业新生</strong>，不是面向全体 EE 本科生的开放班。通知还列有选拔、退出及后续可能增补的机制，具体资格以当届文件为准。</p><h3 id="怎么参与-2" tabindex="-1">怎么参与 <a class="header-anchor" href="#怎么参与-2" aria-label="Permalink to &quot;怎么参与&quot;">​</a></h3><p>符合对应年度资格的同学，应比较荣誉班与普通 CS 培养方案，特别关注课程前置和科研时间安排，再按选拔通知申请。2026 年通知中的报名与考试已是历史安排；未来是否有增补或新一届选拔，应等待学院正式发布。</p><p><strong>官方入口</strong>：<a href="https://sist.shanghaitech.edu.cn/2026/0806/c2863a1126258/page.htm" target="_blank" rel="noreferrer">2026 级人工智能荣誉班选拔通知</a>。</p><h2 id="电子信息专业学位校企联合培养" tabindex="-1">电子信息专业学位校企联合培养 <a class="header-anchor" href="#电子信息专业学位校企联合培养" aria-label="Permalink to &quot;电子信息专业学位校企联合培养&quot;">​</a></h2><h3 id="是什么-3" tabindex="-1">是什么 <a class="header-anchor" href="#是什么-3" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><p>信息学院面向产业需求建设的专业学位联合培养体系。2026 年夏令营官方报道指出，学院自 2020 年起先后与<strong>沐曦集成电路、上海汽车芯片工程中心、北京开源芯片研究院</strong>等单位共建专硕、改革专项直博联合培养项目，研究与实践覆盖集成电路、人工智能及先进电子系统等方向。</p><p>这是多个合作项目组成的体系，不是每家单位每年都以相同条件招生，也不代表短期夏令营等同于正式录取或进入企业就业。</p><h3 id="面向谁-3" tabindex="-1">面向谁 <a class="header-anchor" href="#面向谁-3" aria-label="Permalink to &quot;面向谁&quot;">​</a></h3><p>希望在学术指导与工程需求之间开展研究的电子信息领域研究生申请者。专业型硕士与改革专项直博的学制、申请要求、导师安排和实践环节可能不同，需逐项目核对。</p><h3 id="怎么参与-3" tabindex="-1">怎么参与 <a class="header-anchor" href="#怎么参与-3" aria-label="Permalink to &quot;怎么参与&quot;">​</a></h3><p>关注学院研究生招生与专业学位夏令营通知，阅读当年联培单位、课题及导师介绍；交流时问清校内外培养地点、工程实践安排、成果要求和知识产权边界，再按相应招生流程申请。不要把某年的合作单位名单当成正在开放的岗位清单。</p><p><strong>官方入口</strong>：<a href="https://sist.shanghaitech.edu.cn/2026/0804/c2858a1126162/page.htm" target="_blank" rel="noreferrer">2026 年电子信息专业学位夏令营报道</a>、<a href="https://sist.shanghaitech.edu.cn/yjszs/" target="_blank" rel="noreferrer">信息学院研究生招生</a>。</p><h2 id="smdl-集成电路工艺制造专项班" tabindex="-1">SMDL 集成电路工艺制造专项班 <a class="header-anchor" href="#smdl-集成电路工艺制造专项班" aria-label="Permalink to &quot;SMDL 集成电路工艺制造专项班&quot;">​</a></h2><h3 id="是什么-4" tabindex="-1">是什么 <a class="header-anchor" href="#是什么-4" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><p>材料器件中心（SMDL）依托微纳制造平台开展的产教融合培养。<strong>2026 年官方调剂公告</strong>使用「上海市集成电路工艺制造专项班」名称，招生涉及电子信息与材料与化工专业学位，强调材料、工艺、器件制造、测试及工程实践。</p><p>中心公开材料介绍了校内教授、行业专家、平台工程师共同参与的培养方式。它与以数字设计工具为主的短期培训不同，重点是<strong>工艺制造与微纳工程能力</strong>；平台介绍见 <a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/research-groups/">科研与工艺平台</a>。</p><h3 id="面向谁-4" tabindex="-1">面向谁 <a class="header-anchor" href="#面向谁-4" aria-label="Permalink to &quot;面向谁&quot;">​</a></h3><p>对集成电路工艺、微纳制造和工程实践有兴趣，并满足相应研究生专业与招生条件的申请者。2026 年公告特别关注材料、机械、光学、电子、物理、化学、集成电路、仪器及相关交叉背景；这些是该年度公告内容，不代表免除正式报考要求。</p><h3 id="怎么参与-4" tabindex="-1">怎么参与 <a class="header-anchor" href="#怎么参与-4" aria-label="Permalink to &quot;怎么参与&quot;">​</a></h3><p>阅读 SMDL 当年招生简章及联合培养项目列表，确认报考学院、专业、方向和申请材料。调剂还需遵守国家调剂系统与学校补充材料流程。<strong>2026 年调剂时间已经结束</strong>，未来年度不可直接照搬当时的名额、分数和志愿代码。</p><p><strong>官方入口</strong>：<a href="https://smdl.shanghaitech.edu.cn/2025/1017/c13310a1115978/page.htm" target="_blank" rel="noreferrer">SMDL 2026 年专业型硕士招生公告</a>、<a href="https://smdl.shanghaitech.edu.cn/2026/0324/c13314a1120175/page.htm" target="_blank" rel="noreferrer">专项班 2026 年调剂公告</a>、<a href="https://smdl.shanghaitech.edu.cn/" target="_blank" rel="noreferrer">SMDL 官网</a>。</p><h2 id="暑期产业实践" tabindex="-1">暑期产业实践 <a class="header-anchor" href="#暑期产业实践" aria-label="Permalink to &quot;暑期产业实践&quot;">​</a></h2><h3 id="是什么-5" tabindex="-1">是什么 <a class="header-anchor" href="#是什么-5" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><p><strong>2026 级 EE 培养方案</strong>在大二暑假列有 <strong>1 学分产业实践</strong>。这类课程帮助学生走出课堂，通过行业与企业调研理解技术、产业链和真实需求，而不是将其等同于企业岗位实习。</p><p>结合 <strong>2026 年「高端装备」方向课程笔记</strong>，可见的课程形式包括行前培训与案头调研、团队实地走访、专题分析、团队及个人报告、总结答辩。这里只概括课程形式，不公开个人行程、团队成员、私人记录或成绩信息；其他主题与学期安排可能不同。</p><h3 id="面向谁-5" tabindex="-1">面向谁 <a class="header-anchor" href="#面向谁-5" aria-label="Permalink to &quot;面向谁&quot;">​</a></h3><p>按本年级培养方案修读产业实践的本科生。是否必修、何时参加、如何分组和考核，应以本人适用方案及当年通知为准。</p><h3 id="怎么参与-5" tabindex="-1">怎么参与 <a class="header-anchor" href="#怎么参与-5" aria-label="Permalink to &quot;怎么参与&quot;">​</a></h3><p>关注学校、学院与书院的课程通知，按要求选题、组队并完成培训。建议行前先梳理受访对象的产业链位置和技术问题，行后区分公开资料、现场观察与个人推断，避免把未公开的企业资料带入公开报告或 Wiki。</p><p><strong>官方入口</strong>：<a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Undergraduate/Degree%20Programmes/2026%20Bachelor%20Degree%20Prorgams%20in%20EE.htm" target="_blank" rel="noreferrer">2026 级 EE 培养方案</a>、<a href="https://sist.shanghaitech.edu.cn/2833/list.htm" target="_blank" rel="noreferrer">本科培养方案索引</a>。</p><h2 id="本研一体课程体系" tabindex="-1">本研一体课程体系 <a class="header-anchor" href="#本研一体课程体系" aria-label="Permalink to &quot;本研一体课程体系&quot;">​</a></h2><h3 id="是什么-6" tabindex="-1">是什么 <a class="header-anchor" href="#是什么-6" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><p>信息学院建设分层分类、互融互通的本硕博一体化课程体系，从导论、基础、专业到高阶课程逐层推进。本科生可在满足先修与选课规定的条件下申请修读研究生层次课程，将高阶学习与本科科研衔接起来。</p><p>例如，<a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/ee291f">EE291F</a> 在年度课程表中列为研究生课程、先修 EE113；<a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/ee219">EE219</a> 强调数字集成电路、数学与编程基础。课程层次是参考，不应只凭年级决定学习顺序。</p><h3 id="面向谁-6" tabindex="-1">面向谁 <a class="header-anchor" href="#面向谁-6" aria-label="Permalink to &quot;面向谁&quot;">​</a></h3><p>已具备相关基础、希望沿某个方向继续深入的学生。课程开放并不等于无先修、无容量限制，也不自动改变本科学位要求或研究生录取资格。</p><h3 id="怎么参与-6" tabindex="-1">怎么参与 <a class="header-anchor" href="#怎么参与-6" aria-label="Permalink to &quot;怎么参与&quot;">​</a></h3><p>从 <a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/">课程地图</a> 确定学习链条，再核对学院年度开课计划、教务系统及任课教师说明。跨层次修课前，确认学分计入方式和课程负担；不要以「抢先修高阶课」替代基础课、实验与项目训练。</p><p><strong>官方入口</strong>：<a href="https://sist.shanghaitech.edu.cn/2835/list.htm" target="_blank" rel="noreferrer">本硕博课程体系</a>、<a href="https://sist.shanghaitech.edu.cn/2711/list.htm" target="_blank" rel="noreferrer">本科培养特色</a>。</p><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><p>本页官方网页核对时间为 <strong>2026-11</strong>；以下年份均为资料本身的版本。</p><ul><li><a href="https://sist.shanghaitech.edu.cn/2024/0715/c2858a1098559/page.htm" target="_blank" rel="noreferrer">2024 年 Cadence 暑期实训报道</a>、<a href="https://sist.shanghaitech.edu.cn/2025/0811/c2858a1114212/page.htm" target="_blank" rel="noreferrer">2025 年第二期实训报道</a>。2026 年内容另参考维护者课程笔记《Cadence 集成电路暑期实训》，与官方简章分开标注。</li><li><a href="https://sist.shanghaitech.edu.cn/2026/0402/c2858a1120477/page.htm" target="_blank" rel="noreferrer">上海创芯学院与上科大 2026 年联合招生简介</a>、<a href="https://www.sisi.edu.cn/" target="_blank" rel="noreferrer">SISI 官网</a>。</li><li><a href="https://sist.shanghaitech.edu.cn/2026/0806/c2863a1126258/page.htm" target="_blank" rel="noreferrer">2026 级人工智能荣誉班选拔通知</a>。</li><li><a href="https://sist.shanghaitech.edu.cn/2026/0804/c2858a1126162/page.htm" target="_blank" rel="noreferrer">2026 年电子信息专业学位优秀大学生夏令营报道</a>。</li><li><a href="https://smdl.shanghaitech.edu.cn/2025/1017/c13310a1115978/page.htm" target="_blank" rel="noreferrer">SMDL 2026 年招生公告</a>、<a href="https://smdl.shanghaitech.edu.cn/2026/0324/c13314a1120175/page.htm" target="_blank" rel="noreferrer">2026 年工艺制造专项班调剂公告</a>。</li><li><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Undergraduate/Degree%20Programmes/2026%20Bachelor%20Degree%20Prorgams%20in%20EE.htm" target="_blank" rel="noreferrer">2026 级 EE 培养方案</a>：依据本地 <code>ee2026_rows.txt</code> 核对产业实践安排；课程形式另参考 2026 年《产业实践：高端装备》笔记，不采用其中个人内容。</li><li><a href="https://sist.shanghaitech.edu.cn/2711/list.htm" target="_blank" rel="noreferrer">信息学院本科生招生介绍</a>、<a href="https://sist.shanghaitech.edu.cn/2835/list.htm" target="_blank" rel="noreferrer">本硕博课程体系</a>、<a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm" target="_blank" rel="noreferrer">2026–2027 学年开课表</a>。</li><li><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Undergraduate/Course%20schedule/EE_sample_core_electives.htm" target="_blank" rel="noreferrer">本科生 EE 专业选修课分类图</a>：跨层次课程规划的选课指导，实际开放、先修与学分归类须按教务规定核实。</li></ul>',70)])])}const u=e(s,[["render",n]]);export{p as __pageData,u as default};
